# =====================================================================
#  education.map - phishing phrases for schools and universities
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : student / staff portal and LMS logins (Moodle, Canvas,
#           Blackboard, Google Classroom), student account deactivation,
#           scholarship and grant awards, tuition fees and refunds,
#           exam results / transcripts / diplomas, staff payroll and
#           salary updates, library accounts, fake student job offers
#
#  Avoided: class schedules, exam timetables, newsletters, event
#           announcements, because schools send real ones every day.
# =====================================================================

# ===== English =====
# Portals / LMS
/(log\s+in|sign\s+in|login)\s+to\s+(your\s+|the\s+)?(student|staff|faculty|university|school)\s+(portal|account|email)\s+to\s+(avoid|verify|confirm|keep|continue)/i
/(moodle|canvas|blackboard|google\s+classroom|office\s+365|student\s+portal)\s+(account\s+)?(will\s+be\s+|has\s+been\s+)?(deactivated|suspended|locked|expired|disabled)/i
/your\s+(student|staff|faculty|edu)\s+(email\s+)?account\s+(will\s+be|has\s+been)\s+(deactivated|suspended|deleted|closed)/i
/(re-?validate|revalidate|verify|upgrade)\s+your\s+(student|staff|faculty|edu|university)\s+(email|account)/i
# Scholarships / grants
/(you\s+have\s+been\s+)?(awarded|selected\s+for|approved\s+for)\s+a\s+(scholarship|grant|bursary|stipend|financial\s+aid)/i
/(claim|accept|confirm)\s+your\s+(scholarship|grant|bursary|stipend|financial\s+aid)\s+(award|offer|now|within|before)/i
# Tuition
/(tuition|school|course)\s+fees?\s+(payment\s+)?(is\s+)?(overdue|outstanding|unpaid|failed)/i
/(tuition|student)\s+refund\s+(is\s+)?(approved|pending|available)/i
# Results / documents
/(view|download|access)\s+(your\s+)?(exam\s+results?|grades?|transcripts?|diploma|certificate|report\s+card)\s+(here|online|via\s+(the\s+)?link)/i
/your\s+(exam\s+results?|grades?|transcript|diploma)\s+(has\s+been|have\s+been|are|is)\s+(withheld|on\s+hold|blocked)/i
# Staff payroll
/(salary|payroll|pay)\s+(increase|adjustment|review|update)\s+(letter|document|notice)\s+(attached|available|for\s+(all\s+)?staff)/i
/(update|confirm|verify)\s+your\s+(payroll|salary|direct\s+deposit|bank)\s+(details|information)\s+(before|to\s+receive|for\s+this\s+month)/i
# Library
/your\s+library\s+account\s+(will\s+be\s+|has\s+been\s+)?(suspended|blocked|expired)/i
# Fake student jobs
/(part-?time|remote)\s+(job|position|assistant|work)[^.]{0,40}(\$|usd|eur|€)\s*\d+\s*(per\s+week|weekly|\/\s?week|a\s+week)/i
/(personal|administrative|research)\s+assistant\s+(position|job)\s+[^.]{0,30}(\$|usd|eur)\s*\d+\s*(weekly|per\s+week)/i

