/(inicie\s+sesi[óo]n|acceda)\s+(en|a)\s+(su\s+)?(portal|cuenta)\s+(del\s+)?(estudiante|alumno|universitari[oa])/iu
/su\s+cuenta\s+(de\s+estudiante|universitaria|institucional)\s+(ser[áa]|ha\s+sido)\s+(desactivada|suspendida)/iu
/(ha\s+sido\s+)?(seleccionad[oa]|beneficiad[oa])\s+(para|con)\s+una\s+beca/iu
/(matr[íi]cula|colegiatura)\s+(pendiente|vencida|impaga)/iu

